function patternNumberCrown(n) {
  let rows = [];
  for (let i = 1; i <= n; i++) {
    let row = '';
    for (let j = 1; j <= i; j++) row += j;
    for (let j = 0; j < 2 * (n - i); j++) row += ' ';
    for (let j = i; j >= 1; j--) row += j;
    rows.push(row);
  }
  return rows.join('\n');
}

