function patternNumberCrown(n) {
  let rows = [];
  let left = '';
  let right = '';
  for (let i = 1; i <= n; i++) {
    left += i;
    right = i + right;
    const spaces = ' '.repeat(2 * (n - i));
    rows.push(left + spaces + right);
  }
  return rows.join('\n');
}
